function placeInTag(wrap, canvasEl, hAlign) {
    if (!wrap || !canvasEl) return;
    resetBarcodeWrapInlineSize(wrap);
    wrap.style.position = 'absolute';
    wrap.style.margin = '0';
    var w = Math.max(40, wrap.offsetWidth || 80);
    var h = Math.max(20, wrap.offsetHeight || 24);
    if (hAlign === 'left') {
        wrap.style.left = pad + 'px';
        wrap.style.right = 'auto';
    } else {
        wrap.style.left = Math.max(pad, canvasEl.clientWidth - w - pad) + 'px';
        wrap.style.right = 'auto';
    }
    if (isDual120) {
        wrap.style.top = Math.max(pad, Math.round((canvasEl.clientHeight - h) / 2)) + 'px';
    } else {
        wrap.style.top = pad + 'px';
    }
}
placeInTag(bc1, c1, isDual120 ? 'left' : 'right');
placeInTag(bc2, c2, isDual120 ? 'right' : 'right');
